class UsageError(Exception):
    """ Raised upon problems with usage of any function, i.e. incorrect parameters, unsupported configuration. """
    pass


class ResultError(Exception):
    """ Raised upon unexpected result of any operation, i.e. incorrect state, active alarm. """
    pass


class BtsTypeError(Exception):
    """ Raised upon problems with BTS type. """
    pass


class UnsupportedBtsType(BtsTypeError, UsageError):
    """ Raised when unsupported BTS type has been used. """
    pass


class StateError(Exception):
    """ Raised upon problems regarding BTS state. """
    pass


class UnsupportedState(StateError, UsageError):
    """ Raised when unsupported state has been used. """
    pass


class UnexpectedState(StateError, ResultError):
    """ Raised when expected state was not reached. """
    pass


class AlarmError(Exception):
    """ Raised upon problems regarding alarms. """
    pass


class UnsupportedAlarm(AlarmError, UsageError):
    """ Raised when unsupported alarm has been used. """
    pass


class UnexpectedAlarm(AlarmError, ResultError):
    """ Raised when expected alarm was not active or inactive. """
    pass


class TimeError(Exception):
    """ Raised upon problems regarding timing. """
    pass


class TimeExceeded(TimeError, ResultError):
    """ Raised when expected time was exceeded. """
    pass


class ConfigError(Exception):
    """ Raised upon problems regarding BTS configuration. """
    pass


class UnsupportedConfig(ConfigError, UsageError):
    """ Raised when used param name, value or dist name are incorrect. """
    pass


class UnexpectedConfig(ConfigError, ResultError):
    """ Raised when BTS configuration is in unexpected state. """
    pass


class TestModelError(Exception):
    """ Raised upon problems regarding Test Model execution. """
    pass


class TestModelUnexpectedResult(TestModelError, ResultError):
    """ Raised when execution of Test Model ended with unexpected result. """
    pass


class RfScanError(Exception):
    """ Raised upon problems regarding RF Scan execution. """
    pass


class RfScanUnexpectedResult(RfScanError, ResultError):
    """ Raised when execution of RF Scan ended with unexpected result. """
    pass


class RfDiagnosticTestError(Exception):
    """ Raised upon problems regarding RF Diagnostic Test execution. """
    pass


class RfDiagnosticTestUnexpectedResult(RfDiagnosticTestError, ResultError):
    """ Raised when execution of RF Diagnostic Test ended with unexpected result. """
    pass


class AntennaLineOnlineMonitoringError(Exception):
    """ Raised upon problems regarding Antenna Line Online Monitoring procedure execution. """
    pass


class AntennaLineOnlineMonitoringUnexpectedResult(AntennaLineOnlineMonitoringError, ResultError):
    """ Raised when execution of Antenna Line Online Monitoring procedure ended with unexpected result. """
    pass
